def is_power_of_two(n):
    """Checks if a positive integer n is a power of two."""
    if n <= 0:
        return False
    return (n & (n - 1) == 0)

# Task: Search for n=3, x in [4, 30]. Check if x^3 + x - 2 is a power of 2.
n = 3
results = []

# x must be > n, so start from x = 4
for x in range(4, 31):
    # Calculate LHS - 2: x^3 + x - 2
    value = x**n + x - 2

    if is_power_of_two(value):
        # If it is a power of two, find k such that 2^k = value
        k = value.bit_length() - 1
        results.append((x, n, k, value))

print("--- Search Results for n=3, 4 <= x <= 30 ---")
if results:
    for x, n, k, value in results:
        print(f"Found solution: (x={x}, n={n}, k={k}). Check: {x}^3 + {x} = {x**n + x}. 2^{k} + 2 = {2**k + 2}. LHS == RHS.")
        print(f"Value checked (x^3 + x - 2): {value} = 2^{k}")
else:
    print("No solutions found in the range x=[4, 30].")

# Search for solutions for n=6: x^6 + x - 2 = 2^k, with x > 6
def check_power_of_two(num):
    if num <= 0:
        return False
    return (num & (num - 1) == 0)

results = {}
for x in range(7, 12): # Testing x up to 11
    lhs = x**6 + x - 2
    is_power_of_two = check_power_of_two(lhs)
    results[x] = (lhs, is_power_of_two)

for x, (lhs, is_p2) in results.items():
    print(f"x={x}: LHS = {lhs}, Power of 2? {is_p2}")

